#!/usr/bin/env julia
#
# Generates test/fixtures/orbit64-v2-facelet-vectors.mjs from a flix-orbit64 checkout.
#
#     julia scripts/generate-orbit64-v2-facelet-fixtures.jl [path-to-flix-orbit64]
#
# The default checkout path is ../flix-orbit64. Needs only Julia's standard
# library. Nothing is computed here: everything is copied verbatim from
#
#   test/TestV2FaceletData.flix   facelet rows, themselves generated by that
#                                 repository's independent Julia program
#                                 tools/format-v2/facelet_vectors.jl
#   FORMAT-V2-SLOTS.md            the normative slot tables, n = 2..15
#   src/Orbit64/Frame.flix        the 24 whole-cube frames
#
# The output is deterministic: running it twice yields identical bytes.

const ROOT = dirname(@__DIR__)
const FLIX = abspath(isempty(ARGS) ? joinpath(ROOT, "..", "flix-orbit64") : ARGS[1])
const OUT = joinpath(ROOT, "test", "fixtures", "orbit64-v2-facelet-vectors.mjs")

read_text(path) = read(joinpath(FLIX, path), String)

# A JSON string literal; the sources contain no control characters.
function quoted(s::AbstractString)
    out = replace(s, "\\" => "\\\\", "\"" => "\\\"")
    return "\"" * out * "\""
end

# ---- facelet rows: (entry id, move text, facelets, token, canonical facelets)

row_pattern = r"^\s*\((\d+), \"([^\"]*)\", \"([^\"]*)\", \"([^\"]*)\", \"([^\"]*)\"\),?$"m
rows = [(parse(Int, m[1]), m[2], m[3], m[4], m[5])
        for m in eachmatch(row_pattern, read_text("test/TestV2FaceletData.flix"))]
isempty(rows) && error("no facelet rows found in TestV2FaceletData.flix")
# Every tuple line must have been parsed: a changed row format must not drop rows silently.
tuple_lines = count(l -> occursin(r"^\s*\(\d+,", l), split(read_text("test/TestV2FaceletData.flix"), "\n"))
length(rows) == tuple_lines ||
    error("parsed $(length(rows)) rows, but the file has $tuple_lines tuple lines")

# Each state is written once for the canonical entry and once for the framed entry of its
# size (ids 2k and 2k + 1): a deleted source row leaves a state with one row only.
pair_count = Dict{Tuple{Int,String,String},Int}()
for (id, moves, facelets, _, _) in rows
    key = (id ÷ 2, moves, facelets)
    pair_count[key] = get(pair_count, key, 0) + 1
end
all(==(2), values(pair_count)) || error("a facelet row has no canonical/framed partner")

commit = strip(read(`git -C $FLIX rev-parse HEAD`, String))
occursin(r"^[0-9a-f]{40}$", commit) || error("cannot read the flix-orbit64 commit")

# ---- frames, in Orbit64.Frame wire order

frame_pattern = r"case (?:\d+|_)\s*=> ((?:Face\.\w :: )+)Nil"
frames = [join(m.match for m in eachmatch(r"(?<=Face\.)\w", m[1]))
          for m in eachmatch(frame_pattern, read_text("src/Orbit64/Frame.flix"))]
length(frames) == 24 || error("expected 24 frames, found $(length(frames))")

# ---- slot tables, from FORMAT-V2-SLOTS.md

mutable struct Slots
    corners::Vector{Vector{Int}}
    midges::Vector{Vector{Int}}
    wings::Vector{Vector{Vector{Int}}}
    centers::Vector{Vector{Int}}
    fixed::Vector{Int}
end

ints(s) = [parse(Int, t) for t in split(strip(s))]

function read_slots(text)
    sizes = Dict{Int,Slots}()
    current = nothing
    for line in split(text, "\n")
        if (m = match(r"^## (\d+)x\d+x\d+$", line)) !== nothing
            current = Slots([], [], [], [], [])
            sizes[parse(Int, m[1])] = current
        elseif current === nothing
            continue
        elseif (m = match(r"^Facelets `0\.\.\d+`\. The fixed centers are `face \* (\d+) \+ (\d+)`", line)) !== nothing
            append!(current.fixed, [f * parse(Int, m[1]) + parse(Int, m[2]) for f in 0:5])
        elseif (m = match(r"^\s+C \d+: (.*)$", line)) !== nothing
            push!(current.corners, ints(m[1]))
        elseif (m = match(r"^\s+M \d+: (.*)$", line)) !== nothing
            push!(current.midges, ints(m[1]))
        elseif (m = match(r"^wings, depth (\d+)$", line)) !== nothing
            push!(current.wings, Vector{Int}[])
        elseif (m = match(r"^\s+W\d+ \d+: (.*)$", line)) !== nothing
            push!(last(current.wings), ints(m[1]))
        elseif (m = match(r"^\s+Z\[\d+,\d+\]: (.*)$", line)) !== nothing
            push!(current.centers, ints(m[1]))
        end
    end
    return sizes
end

slots = read_slots(read_text("FORMAT-V2-SLOTS.md"))
sort(collect(keys(slots))) == collect(2:15) || error("expected slot tables for n = 2..15")

# ---- output

list(items, f) = "[" * join((f(x) for x in items), ",") * "]"
ints_js(v) = list(v, string)
nested(v) = list(v, ints_js)

io = IOBuffer()
println(io, "// Generated by scripts/generate-orbit64-v2-facelet-fixtures.jl. Do not edit.")
println(io, "//")
println(io, "// Source: flix-orbit64 (the Flix reference implementation of FORMAT-V2.md),")
println(io, "// commit ", commit, ".")
println(io, "//   faceletRows   test/TestV2FaceletData.flix, itself generated by that repository's")
println(io, "//                 independent Julia program tools/format-v2/facelet_vectors.jl. Rows are")
println(io, "//                 [entry id, move text, facelets, token, canonical facelets or \"\"].")
println(io, "//                 The last column is empty when the canonical facelets equal the given ones.")
println(io, "//   slotTables    FORMAT-V2-SLOTS.md, n = 2..15: corners, midges, wings by depth and")
println(io, "//                 center orbits, each slot the list of its facelet indexes, and the")
println(io, "//                 fixed centers of odd cubes.")
println(io, "//   frameFaces    src/Orbit64/Frame.flix: the physical face in each slot U R F D L B.")
println(io)
println(io, "export const faceletRows = [")
for (id, moves, facelets, token, canonical) in rows
    println(io, "  [", id, ",", quoted(moves), ",", quoted(facelets), ",", quoted(token), ",",
            quoted(canonical), "],")
end
println(io, "];")
println(io)
println(io, "export const slotTables = {")
for n in 2:15
    s = slots[n]
    println(io, "  ", n, ": {")
    println(io, "    corners: ", nested(s.corners), ",")
    println(io, "    midges: ", nested(s.midges), ",")
    println(io, "    wings: ", list(s.wings, nested), ",")
    println(io, "    centers: ", nested(s.centers), ",")
    println(io, "    fixed: ", ints_js(s.fixed), ",")
    println(io, "  },")
end
println(io, "};")
println(io)
println(io, "export const frameFaces = ", list(frames, quoted), ";")

write(OUT, take!(io))
println("wrote $(length(rows)) facelet rows, slot tables for n = 2..15 and $(length(frames)) frames")
